import fcntl
import json
import math
import os


def append_once(path, record):
    """Append a finite JSON record under a cooperating POSIX flock."""
    def validate(value):
        if value is None or type(value) in (str, bool, int):
            return
        if type(value) is float:
            if not math.isfinite(value):
                raise ValueError("Non-finite JSON number")
            return
        if type(value) is list:
            for item in value:
                validate(item)
            return
        if type(value) is dict:
            for key, item in value.items():
                if type(key) is not str:
                    raise ValueError("JSON object keys must be strings")
                validate(item)
            return
        raise ValueError("Not a JSON value")

    def canonical(row):
        if type(row) is not dict:
            raise ValueError("Record must be a JSON object")
        if type(row.get("id")) is not str or not row["id"]:
            raise ValueError("Record needs a nonempty string id")
        validate(row)
        return json.dumps(row, allow_nan=False, sort_keys=True,
                          separators=(",", ":"), ensure_ascii=True)

    def pairs(items):
        result = {}
        for key, value in items:
            if key in result:
                raise ValueError("Duplicate JSON object key")
            result[key] = value
        return result

    def bad_constant(value):
        raise ValueError("Non-finite JSON constant: " + value)

    # Complete serialization before opening or changing the ledger.
    incoming = canonical(record)
    payload = (incoming + "\n").encode("utf-8")
    record_id = json.loads(incoming)["id"]
    with open(path, "a+b") as ledger:
        fcntl.flock(ledger.fileno(), fcntl.LOCK_EX)
        try:
            ledger.seek(0)
            seen = {}
            last_line = b""
            for line in ledger:
                try:
                    row = json.loads(line.decode("utf-8"),
                                     object_pairs_hook=pairs,
                                     parse_constant=bad_constant)
                    normalized = canonical(row)
                except (ValueError, TypeError, UnicodeError, RecursionError) as exc:
                    raise ValueError("Malformed ledger row") from exc
                if row["id"] in seen:
                    raise ValueError("Duplicate ledger id")
                seen[row["id"]] = normalized
                last_line = line
            if record_id in seen:
                if seen[record_id] != incoming:
                    raise ValueError("Existing id has different content")
                return False
            separator = b"\n" if last_line and not last_line.endswith(b"\n") else b""
            ledger.seek(0, os.SEEK_END)
            ledger.write(separator + payload)
            ledger.flush()
            os.fsync(ledger.fileno())
            return True
        finally:
            fcntl.flock(ledger.fileno(), fcntl.LOCK_UN)
